#!/usr/bin/env python3
"""Self-contained Kaggle entry point v2: pipeline payload embedded as base64."""
import base64
import io
import runpy
import subprocess
import sys
import zipfile
from pathlib import Path

PAYLOAD_B64 = ""
WORK = Path("/kaggle/working")
PKG = WORK / "pkg"


def main():
    PKG.mkdir(parents=True, exist_ok=True)
    print("Extracting payload ...", flush=True)
    data = base64.b64decode(PAYLOAD_B64)
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(PKG)
    py = sys.executable
    print("Installing requirements ...", flush=True)
    subprocess.check_call(
        [py, "-m", "pip", "install", "--quiet", "-r",
         str(PKG / "requirements-kaggle.txt")]
    )
    print("Requirements installed. Starting v2 pipeline ...", flush=True)
    runpy.run_path(str(PKG / "run_all_v2.py"), run_name="__main__")


if __name__ == "__main__":
    main()
